-- PBI-006: compras a proveedores. Cada línea suma stock; anular (solo Administrador) lo revierte.
create table if not exists public.compras (
  "Id_Compras" integer generated by default as identity primary key,
  "Id_Personas" integer not null references public.personas("Id_Personas") on delete restrict,
  "Fecha" timestamp not null default now(),
  "Comprobante" varchar(50) null,
  "Total" numeric(18,0) not null default 0 check ("Total" >= 0),
  "Estado" varchar(20) not null default 'Registrada' check ("Estado" in ('Registrada', 'Anulada')),
  "Id_Usuarios" integer not null references public.usuarios("Id_Usuarios"),
  "FechaAnulacion" timestamp null,
  "Id_Usuarios_Anulacion" integer null references public.usuarios("Id_Usuarios"),
  "MotivoAnulacion" varchar(250) null
);

create table if not exists public.compras_detalle (
  "Id_Compras_Detalle" integer generated by default as identity primary key,
  "Id_Compras" integer not null references public.compras("Id_Compras") on delete cascade,
  "Id_Productos" integer not null references public.productos("Id_Productos") on delete restrict,
  "Cantidad" numeric(18,0) not null check ("Cantidad" > 0),
  "PrecioUnitario" numeric(18,0) not null check ("PrecioUnitario" >= 0),
  "Subtotal" numeric(18,0) not null check ("Subtotal" >= 0)
);

create index if not exists ix_compras_proveedor on public.compras ("Id_Personas", "Fecha");
